"""Static review authoring data. Reads source text; never imports or runs project code."""
from pathlib import Path
import json, html, hashlib, re, subprocess
ROOT=Path(__file__).resolve().parents[2]
OUT=ROOT/'Current_State'
COMMIT='09f32690ffca5d9c79f6d8702481f6efe30a4cf3'
PIN=f'https://github.com/cschadewitz/Project_Orca/blob/{COMMIT}/'
VIEWS=[]
def ev(path,needle):
    text=(ROOT/path).read_text()
    pos=text.find(needle)
    if pos<0: raise ValueError((path,needle))
    return {'path':path,'line':text[:pos].count('\n')+1,'symbol':needle}
def link(e,prefix='../../'):
    return f'[`{e["symbol"]}`]({prefix}{e["path"]}#L{e["line"]}) ([pinned]({PIN}{e["path"]}#L{e["line"]}))'
def add(key,title,owner,scope,claims,nodes,edges,limits='',kind='component'):
    evidence=[];c=[]
    for item in claims:
        level,statement,path,needle=item
        evidence.append(ev(path,needle));c.append({'classification':level,'statement':statement,'evidence':len(evidence)})
    VIEWS.append(dict(id=key,title=title,owner=owner,scope=scope,kind=kind,claims=c,evidence=evidence,
                      nodes=[{'id':str(i+1),'label':n[0],'type':n[1]} for i,n in enumerate(nodes)],
                      edges=[{'from':str(a),'to':str(b),'label':l,'type':t,'evidence':e} for a,b,l,t,e in edges],limits=limits))
